function AuthPage({ signUp = false }: { signUp?: boolean }) {
  const [, setLocation] = useLocation();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const destination = (role: string) => role === 'admin' ? '/admin/dashboard' : role === 'staff' ? '/staff/dashboard' : '/customer';
  const submit = async (event: FormEvent) => {
    event.preventDefault();
    setError(null); setMessage(null);
    if (!supabase || !authConfigured) { setError('Sign-in is not configured for this environment.'); return; }
    setSubmitting(true);
    try {
      if (signUp) {
        const { data, error: signUpError } = await supabase.auth.signUp({ email, password, options: { data: { name }, emailRedirectTo: `${window.location.origin}/sign-in` } });
        if (signUpError) throw signUpError;
        if (!data.session) setMessage('Check your email to confirm your customer account, then sign in.');
        else {
          const { getCurrentUser } = await import('@workspace/api-client-react');
          const profile = await getCurrentUser();
          setLocation(destination(profile.role));
        }
      } else {
        const { error: signInError } = await supabase.auth.signInWithPassword({ email, password });
        if (signInError) throw signInError;
        // AuthProvider fetches /me after the verified Supabase session is stored.
        const { getCurrentUser } = await import('@workspace/api-client-react');
        const profile = await getCurrentUser();
        setLocation(destination(profile.role));
      }
    } catch {
      setError(signUp ? 'We could not create your account. Check the details and try again.' : 'Invalid email or password.');
    } finally { setSubmitting(false); }
  };
  return <div className="grid min-h-[100dvh] place-items-center bg-background p-5"><div className="w-full max-w-[430px]"><Brand /><Card className="mt-10 p-7 md:p-9"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-primary">SANFAANI</p><h1 className="mt-3 font-serif text-4xl">{signUp ? 'Create your account.' : 'Welcome back.'}</h1><p className="mt-2 text-sm text-muted-foreground">{signUp ? 'Public registration creates a customer account.' : 'Sign in with your SANFAANI account.'}</p><form className="mt-8 space-y-4" onSubmit={submit}>{signUp && <label className="block text-xs font-semibold uppercase tracking-wider text-muted-foreground">Name<input required value={name} onChange={e => setName(e.target.value)} className="mt-2 h-12 w-full rounded-md border border-input bg-muted/50 px-3 outline-none focus:border-primary" placeholder="Your name" data-testid="input-name" /></label>}<label className="block text-xs font-semibold uppercase tracking-wider text-muted-foreground">Email<input required value={email} onChange={e => setEmail(e.target.value)} className="mt-2 h-12 w-full rounded-md border border-input bg-muted/50 px-3 outline-none focus:border-primary" type="email" placeholder="you@example.com" data-testid="input-email" /></label><label className="block text-xs font-semibold uppercase tracking-wider text-muted-foreground">Password<input required minLength={6} value={password} onChange={e => setPassword(e.target.value)} className="mt-2 h-12 w-full rounded-md border border-input bg-muted/50 px-3 outline-none focus:border-primary" type="password" autoComplete={signUp ? 'new-password' : 'current-password'} placeholder="At least 6 characters" data-testid="input-password" /></label>{error && <p className="text-sm text-destructive" data-testid="auth-error">{error}</p>}{message && <p className="text-sm text-secondary" data-testid="auth-message">{message}</p>}<Button className="w-full" type="submit" disabled={submitting}>{submitting ? 'Please wait…' : signUp ? 'Create customer account' : 'Sign in'} <ChevronRight size={15} /></Button></form>{!signUp && <Link className="mt-4 block text-center text-xs font-semibold text-primary hover:underline" href="/forgot-password">Forgot your password?</Link>}<p className="mt-6 text-center text-xs text-muted-foreground">{signUp ? 'Already have an account?' : 'New to SANFAANI?'} <Link className="font-semibold text-primary hover:underline" href={signUp ? '/sign-in' : '/sign-up'} data-testid="link-auth-switch">{signUp ? 'Sign in' : 'Create account'}</Link></p></Card><Link href="/" className="mt-6 flex justify-center text-xs text-muted-foreground hover:text-foreground" data-testid="link-back-home">Return to landing</Link></div></div>;
}

function ForgotPasswordPage() {
  const [email, setEmail] = useState(''); const [error, setError] = useState<string | null>(null); const [sent, setSent] = useState(false); const [submitting, setSubmitting] = useState(false);
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(null); if (!supabase) { setError('Password recovery is not configured.'); return; } setSubmitting(true); const { error: resetError } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/reset-password` }); setSubmitting(false); if (resetError) setError('We could not send a reset email. Please try again.'); else setSent(true); };
  return <div className="grid min-h-[100dvh] place-items-center bg-background p-5"><div className="w-full max-w-[430px]"><Brand /><Card className="mt-10 p-7 md:p-9"><h1 className="font-serif text-4xl">Reset password</h1><p className="mt-2 text-sm text-muted-foreground">Enter your email and we will send a secure reset link.</p><form className="mt-8 space-y-4" onSubmit={submit}><label className="block text-xs font-semibold uppercase tracking-wider text-muted-foreground">Email<input required type="email" value={email} onChange={e => setEmail(e.target.value)} className="mt-2 h-12 w-full rounded-md border border-input bg-muted/50 px-3" /></label>{error && <p className="text-sm text-destructive">{error}</p>}{sent && <p className="text-sm text-secondary">If an account exists for that email, a reset link has been sent.</p>}<Button className="w-full" disabled={submitting}>{submitting ? 'Sending…' : 'Send reset link'}</Button></form><Link href="/sign-in" className="mt-5 block text-center text-xs font-semibold text-primary">Back to sign in</Link></Card></div></div>;
}

function ResetPasswordPage() {
  const [, setLocation] = useLocation(); const { session } = useAuth(); const [password, setPassword] = useState(''); const [error, setError] = useState<string | null>(null); const [submitting, setSubmitting] = useState(false);
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(null); if (!supabase || !session) { setError('This password reset link is invalid or has expired. Request a new one.'); return; } setSubmitting(true); const { error: updateError } = await supabase.auth.updateUser({ password }); setSubmitting(false); if (updateError) setError('This password reset link is invalid or has expired. Request a new one.'); else { await supabase.auth.signOut(); setLocation('/sign-in'); } };
  return <div className="grid min-h-[100dvh] place-items-center bg-background p-5"><div className="w-full max-w-[430px]"><Brand /><Card className="mt-10 p-7 md:p-9"><h1 className="font-serif text-4xl">Set a new password</h1><p className="mt-2 text-sm text-muted-foreground">Choose a new password for your SANFAANI account.</p><form className="mt-8 space-y-4" onSubmit={submit}><label className="block text-xs font-semibold uppercase tracking-wider text-muted-foreground">New password<input required minLength={6} type="password" value={password} onChange={e => setPassword(e.target.value)} className="mt-2 h-12 w-full rounded-md border border-input bg-muted/50 px-3" /></label>{error && <p className="text-sm text-destructive">{error}</p>}<Button className="w-full" disabled={submitting}>{submitting ? 'Saving…' : 'Set new password'}</Button></form><Link href="/forgot-password" className="mt-5 block text-center text-xs font-semibold text-primary">Request a new link</Link></Card></div></div>;
}

function RequireAuth({ children }: { children: ReactNode }) {
  const { session, loading } = useAuth();
  if (loading) return <LoadingState />;
  return session ? <>{children}</> : <Redirect to="/sign-in" />;
}

function RequireRole({ roles, children }: { roles: Array<'admin' | 'staff' | 'customer'>; children: ReactNode }) {
  const { profile, loading } = useAuth();
  if (loading) return <LoadingState />;
  if (!profile) return <Redirect to="/sign-in" />;
  if (!roles.includes(profile.role)) return <Redirect to={profile.role === 'customer' ? '/customer' : '/staff/dashboard'} />;
  return <>{children}</>;
}

function Dashboard() {
  const { data, isLoading, isError, refetch, isFetching } = useGetDashboardSummary({ query: { queryKey: getGetDashboardSummaryQueryKey() } });
  const { profile } = useAuth();
  const summary = data;
  const metrics = summary ? [
    { label: 'TODAY’S REVENUE', value: money(summary.todayRevenue), Icon: ArrowUpRight, color: 'text-primary' },
    { label: 'CUSTOMERS TODAY', value: summary.todayCustomers, Icon: Users, color: 'text-[#75d6bd]' },
    { label: 'LOW STOCK ITEMS', value: summary.lowStockCount, Icon: CircleAlert, color: 'text-primary' },
    { label: 'READY TO COLLECT', value: summary.readySessions.length, Icon: Check, color: 'text-[#75d6bd]' },
  ] : [];
  return <><PageHead eyebrow="Live overview" title={`Welcome, ${profile?.email?.split('@')[0] ?? 'operator'}.`} description="Here is the operating picture for your floor today." action={<Button variant="ghost" onClick={() => void refetch()} disabled={isFetching} data-testid="button-refresh-dashboard"><RefreshCw size={15} /> {isFetching ? 'Refreshing…' : 'Refresh view'}</Button>} /><QueryState loading={isLoading} error={isError}>{summary && <div className="animate-rise space-y-7">
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{metrics.map(({ label, value, Icon, color }) => <Card key={label} className="relative overflow-hidden p-5"><div className="flex items-start justify-between"><p className="font-mono text-[10px] tracking-[.16em] text-muted-foreground">{label}</p><Icon size={17} className={color} /></div><p className="mt-6 font-mono text-3xl text-foreground">{value}</p><div className="absolute bottom-0 left-0 h-0.5 w-1/3 bg-primary" /></Card>)}</div>
    <div className="grid gap-7 xl:grid-cols-[1.05fr_.95fr]"><Card className="p-5 md:p-6"><SectionTitle action={<Link href="/admin/charging" className="text-[10px] font-bold uppercase tracking-widest text-primary" data-testid="link-view-charging">View charging <ChevronRight size={12} className="inline" /></Link>}>Charging floor</SectionTitle><div className="grid gap-5 md:grid-cols-[1fr_1fr]"><CapacityBattery label="Charging bays" current={summary.charging.active} maximum={summary.charging.capacity} /><CapacityBattery label="Workspace desks" current={summary.workspace.occupied} maximum={summary.workspace.capacity} /></div><div className="mt-6 grid grid-cols-3 gap-2">{[['ACTIVE', summary.charging.active], ['AVAILABLE', summary.charging.available], ['CAPACITY', summary.charging.capacity]].map(([label, v]) => <div key={label as string} className="rounded-md bg-muted/50 p-3"><p className="font-mono text-[9px] text-muted-foreground">{label as string}</p><p className="mt-1 font-mono text-xl">{v as number}</p></div>)}</div></Card><Card className="p-5 md:p-6"><SectionTitle action={<Link href="/admin/transactions" className="text-[10px] font-bold uppercase tracking-widest text-primary" data-testid="link-view-ledger">Open ledger <ChevronRight size={12} className="inline" /></Link>}>Recent transactions</SectionTitle><div className="space-y-1">{summary.recentTransactions.slice(0, 5).map(t => <TransactionRow key={t.id} {...t} />)}</div></Card></div>
    <div className="grid gap-7 xl:grid-cols-[1.05fr_.95fr]"><Card className="p-5 md:p-6"><SectionTitle>Ready for collection</SectionTitle><QueryState empty={!summary.readySessions.length}>{summary.readySessions.map(s => <ReadyRow key={s.id} session={s} />)}</QueryState></Card><Card className="p-5 md:p-6"><SectionTitle action={<Link href="/admin/inventory" className="text-[10px] font-bold uppercase tracking-widest text-primary" data-testid="link-view-inventory">Inventory <ChevronRight size={12} className="inline" /></Link>}>Stock watch</SectionTitle><div className="space-y-3">{summary.lowStockProducts.map(p => <div key={p.id} className="flex items-center justify-between border-b border-border pb-3 last:border-0"><div className="flex items-center gap-3"><span className="grid h-8 w-8 place-items-center rounded-md bg-primary/10 text-primary"><PackagePlus size={15} /></span><div><p className="text-sm font-semibold">{p.name}</p><p className="font-mono text-[10px] text-muted-foreground">{p.sku}</p></div></div><span className="font-mono text-xs text-primary">{p.quantityOnHand} left</span></div>)}</div></Card></div>
  </div>}</QueryState></>;
}
function TransactionRow({ description, amount, direction, paymentMethod, createdAt }: { description: string; amount: number; direction: string; paymentMethod: string; createdAt: string }) { return <div className="flex items-center gap-3 border-b border-border py-3 last:border-0"><span className={`grid h-8 w-8 place-items-center rounded-full ${direction === 'income' ? 'bg-[#5cc7ac]/10 text-[#75d6bd]' : 'bg-destructive/10 text-destructive'}`}>{direction === 'income' ? <ArrowDownLeft size={14} /> : <ArrowUpRight size={14} />}</span><div className="min-w-0 flex-1"><p className="truncate text-sm">{description}</p><p className="font-mono text-[9px] uppercase text-muted-foreground">{paymentMethod} · {dateTime(createdAt)}</p></div><span className={`font-mono text-sm ${direction === 'income' ? 'text-[#75d6bd]' : 'text-destructive'}`}>{direction === 'income' ? '+' : '-'}{money(amount)}</span></div>; }
function ReadyRow({ session }: { session: ChargingSession }) { return <div className="mb-3 flex items-center gap-4 rounded-md border border-primary/20 bg-primary/5 p-4 last:mb-0"><div className="grid h-10 w-10 place-items-center rounded-md bg-primary/15 text-primary"><Smartphone size={19} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-semibold">{session.customerName}</p><Status tone="good">Ready</Status></div><p className="mt-1 font-mono text-[10px] uppercase text-muted-foreground">{session.device.brand ?? session.device.type} · Bay {session.slotNumber} · {session.publicSessionId}</p></div><Link href="/admin/charging" className="grid h-9 w-9 place-items-center rounded-md border border-border text-muted-foreground hover:text-primary" data-testid={`link-ready-session-${session.id}`}><ChevronRight size={16} /></Link></div>; }

function Charging() {
  const q = useListChargingSessions({ query: { queryKey: getListChargingSessionsQueryKey() } });
  const summary = useGetDashboardSummary({ query: { queryKey: getGetDashboardSummaryQueryKey() } });
  const qc = useQueryClient(); const update = useUpdateChargingStatus(); const collect = useCollectChargingSession(); const verify = useVerifyChargingClaim();
  const [collection, setCollection] = useState<ChargingSession | null>(null); const [claimId, setClaimId] = useState(''); const [collectionError, setCollectionError] = useState<string | null>(null); const [scannerOpen, setScannerOpen] = useState(false);
  const invalidate = () => Promise.all([qc.invalidateQueries({ queryKey: getListChargingSessionsQueryKey() }), qc.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }), qc.invalidateQueries({ queryKey: getListReceiptsQueryKey() }), qc.invalidateQueries({ queryKey: getListTransactionsQueryKey() }), qc.invalidateQueries({ queryKey: getListHistoryQueryKey() })]);
  const act = (id: string, status: 'charging' | 'ready' | 'cancelled') => update.mutate({ id, data: { status } }, { onSuccess: () => { void invalidate(); toast.success(status === 'ready' ? 'Device marked ready. The customer has been notified.' : 'Charging status updated.'); }, onError: () => toast.error('Could not update the charging status. Please try again.') });
  const capacityFull = summary.data ? summary.data.charging.available <= 0 : false;
  const active = summary.data?.charging.active ?? q.data?.length ?? 0;
  const capacity = summary.data?.charging.capacity ?? 0;
  return <><PageHead eyebrow="Service station" title="Charging floor" description="Move every device through its lifecycle with a clean handoff." action={<div className="flex flex-wrap gap-2"><Button variant="ghost" onClick={() => setScannerOpen(true)} data-testid="button-scan-claim"><ScanLine size={16} /> Scan claim</Button>{capacityFull ? <Button disabled data-testid="button-charging-full"><CircleAlert size={16} /> Charging capacity reached</Button> : <Link href="/admin/charging/new" className="inline-flex min-h-11 items-center justify-center gap-2 rounded-md bg-primary px-4 text-xs font-bold uppercase tracking-widest text-primary-foreground" data-testid="link-new-charging"><Plus size={16} /> Check in device</Link>}</div>} />{capacityFull && <p className="-mt-4 mb-6 rounded-md border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">Charging capacity reached. 0 slots available.</p>}<div className="mb-7 grid gap-4 sm:grid-cols-3"><CapacityCard label="Active sessions" value={active} icon={BatteryCharging} /><CapacityCard label="Ready for collection" value={q.data?.filter(s => s.status === 'ready').length ?? 0} icon={Check} accent="teal" /><CapacityCard label="Open bays" value={summary.data?.charging.available ?? Math.max(0, capacity - active)} icon={Store} /></div>{summary.data && <Card className="mb-7 p-5"><CapacityBattery label="Charging capacity" current={summary.data.charging.active} maximum={summary.data.charging.capacity} /></Card>}<Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[800px] text-left"><thead><tr className="border-b border-border bg-muted/30 font-mono text-[10px] uppercase tracking-widest text-muted-foreground"><th className="px-5 py-4">Device / customer</th><th>Bay</th><th>Checked in</th><th>Status</th><th>Payment</th><th className="px-5">Action</th></tr></thead><tbody><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(s => <tr key={s.id} className="border-b border-border last:border-0 hover:bg-muted/20" data-testid={`row-charging-${s.id}`}><td className="px-5 py-4"><p className="font-semibold">{s.customerName}</p><p className="font-mono text-[10px] text-muted-foreground">{s.device.brand ?? s.device.type} {s.device.model ?? ''} · {s.publicSessionId}</p></td><td className="font-mono text-sm">B-{String(s.slotNumber).padStart(2, '0')}</td><td className="font-mono text-xs text-muted-foreground">{dateTime(s.timeIn)}</td><td><Status tone={s.status === 'ready' ? 'good' : s.status === 'cancelled' ? 'bad' : 'warn'}>{s.status}</Status></td><td><span className="font-mono text-sm">{money(s.amount)}</span><small className="ml-2 text-[10px] text-muted-foreground">{s.paymentStatus}</small></td><td className="px-5">{s.status === 'ready' ? <Button variant="teal" className="min-h-9 px-3 text-[10px]" onClick={() => { setCollection(s); setClaimId(''); setCollectionError(null); }} data-testid={`button-collect-${s.id}`}><Check size={14} /> Collect</Button> : s.status === 'charging' ? <Button variant="ghost" className="min-h-9 px-3 text-[10px]" disabled={update.isPending} onClick={() => act(s.id, 'ready')} data-testid={`button-ready-${s.id}`}>Mark ready</Button> : s.status === 'checked-in' ? <Button variant="ghost" className="min-h-9 px-3 text-[10px]" disabled={update.isPending} onClick={() => act(s.id, 'charging')} data-testid={`button-start-${s.id}`}>Start charge</Button> : <span className="text-xs text-muted-foreground">No action</span>}</td></tr>)}</QueryState></tbody></table></div></Card>{scannerOpen && <Modal title="Scan secure claim" onClose={() => setScannerOpen(false)}><div className="pt-5"><Suspense fallback={<LoadingState />}><ClaimScanner onScan={(token) => verify.mutate({ data: { token } }, { onSuccess: (result) => { const session = q.data?.find((item) => item.id === result.sessionId); if (!session) { toast.error('Verified claim is not present on the active floor.'); return; } setClaimId(token); setCollection(session); setCollectionError(null); setScannerOpen(false); toast.success('Secure claim verified. Confirm release details.'); }, onError: () => toast.error('This QR claim is invalid, used, or the device is not ready.') })} /></Suspense>{verify.isPending && <p className="mt-3 text-sm text-primary">Verifying secure claim…</p>}</div></Modal>}{collection && <Modal title="Release device" onClose={() => setCollection(null)}><p className="text-sm text-muted-foreground">Confirm the claim before releasing {collection.device.brand ?? collection.device.type} for {collection.customerName}.</p><div className="mt-4 rounded-md bg-muted/50 p-3 font-mono text-xs"><p>Claim: {collection.publicSessionId}</p><p className="mt-1">Bay B-{String(collection.slotNumber).padStart(2, '0')}</p></div><label className="mt-5 block text-xs font-semibold uppercase tracking-wider text-muted-foreground">Claim code<input autoFocus value={claimId} onChange={e => setClaimId(e.target.value)} className="mt-2 h-12 w-full rounded-md border border-input bg-muted/50 px-3 font-mono outline-none focus:border-primary" placeholder="Enter Claim ID or scan QR" data-testid="input-claim-code" /></label>{collectionError && <p className="mt-3 text-sm text-destructive">{collectionError}</p>}<Button className="mt-5 w-full" onClick={() => { if (claimId.trim().length < 10) { setCollectionError('Enter the complete claim code before releasing this device.'); return; } collect.mutate({ id: collection.id, data: { claimId: claimId.trim() } }, { onSuccess: () => { setCollection(null); void invalidate(); toast.success('Device collected and charging bay released.'); }, onError: () => setCollectionError('The claim code could not be verified, is already used, or the device is not ready.') }); }} disabled={collect.isPending} data-testid="button-confirm-collection">{collect.isPending ? 'Verifying…' : 'Verify and release'}</Button></Modal>}</>;
}
function CapacityCard({ label, value, icon: Icon, accent = 'amber' }: { label: string; value: number; icon: typeof BatteryCharging; accent?: 'amber' | 'teal' }) { return <Card className="p-5"><div className="flex justify-between"><p className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">{label}</p><Icon size={16} className={accent === 'teal' ? 'text-secondary' : 'text-primary'} /></div><p className="mt-5 font-mono text-3xl">{value}</p></Card>; }
function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { return <div className="fixed inset-0 z-50 grid place-items-center bg-black/70 p-5" role="presentation" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><div role="dialog" aria-modal="true" aria-label={title} className="w-full max-w-md rounded-lg border border-border bg-card p-6 shadow-2xl"><div className="flex items-center justify-between"><h2 className="font-serif text-2xl">{title}</h2><button onClick={onClose} className="rounded p-1 text-muted-foreground hover:bg-muted" data-testid="button-close-modal" aria-label="Close dialog"><X size={18} /></button></div>{children}</div></div>; }

function ChargingNew() {
  const checkIn = useCheckInChargingSession(); const [, setLocation] = useLocation();
  const summary = useGetDashboardSummary({ query: { queryKey: getGetDashboardSummaryQueryKey() } });
  const [form, setForm] = useState<Partial<ChargingCheckInInput>>({ deviceType: 'phone', expectedMinutes: 90, paymentMethod: 'cash', amount: 500 });
  const [created, setCreated] = useState<ChargingCheckInResult | null>(null);
  const set = (key: string, value: string | number) => setForm(f => ({ ...f, [key]: value }));
  const full = summary.data ? summary.data.charging.available <= 0 : false;
  const submit = () => checkIn.mutate({ data: form as ChargingCheckInInput }, { onSuccess: (result) => { setCreated(result); toast.success('Device checked in and receipt created.'); }, onError: () => toast.error(full ? 'Charging capacity reached.' : 'Check-in could not be completed. Review the details and try again.') });
  return <><PageHead eyebrow="New session" title="Check in a device" description="Capture the handoff cleanly. The system will assign the next available bay." />{full && <p className="mb-5 rounded-md border border-destructive/40 bg-destructive/10 p-4 text-sm text-destructive">Charging capacity reached. Return to the charging floor when a bay is released.</p>}<Card className="max-w-3xl p-6 md:p-8"><div className="grid gap-5 md:grid-cols-2"><Field label="Customer name" value={form.customerName ?? ''} onChange={v => set('customerName', v)} test="input-customer-name" /><Field label="Phone number" value={form.phone ?? ''} onChange={v => set('phone', v)} test="input-phone" /><SelectField label="Device type" value={form.deviceType ?? 'phone'} onChange={v => set('deviceType', v)} options={['phone', 'laptop', 'tablet', 'powerbank', 'other']} test="select-device-type" /><Field label="Brand" value={form.brand ?? ''} onChange={v => set('brand', v)} test="input-brand" /><Field label="Model" value={form.model ?? ''} onChange={v => set('model', v)} test="input-model" /><Field label="Colour" value={form.color ?? ''} onChange={v => set('color', v)} test="input-color" /><Field label="Description" value={form.description ?? ''} onChange={v => set('description', v)} test="input-description" /><Field label="Expected minutes" type="number" value={String(form.expectedMinutes ?? 90)} onChange={v => set('expectedMinutes', Number(v))} test="input-expected-minutes" /><Field label="Amount" type="number" value={String(form.amount ?? 500)} onChange={v => set('amount', Number(v))} test="input-amount" /><SelectField label="Payment method" value={form.paymentMethod ?? 'cash'} onChange={v => set('paymentMethod', v)} options={['cash', 'transfer', 'card', 'other']} test="select-payment-method" /></div><div className="mt-7 flex flex-col-reverse gap-3 border-t border-border pt-6 sm:flex-row sm:justify-end"><Button variant="ghost" onClick={() => setLocation('/admin/charging')} data-testid="button-cancel-checkin">Cancel</Button><Button disabled={checkIn.isPending || full || !form.customerName || !form.phone || !form.deviceType || Number(form.amount) < 0} onClick={submit} data-testid="button-submit-checkin"><BatteryCharging size={16} />{checkIn.isPending ? 'Checking in…' : 'Check in device'}</Button></div>{checkIn.isError && <p className="mt-4 text-sm text-destructive" data-testid="status-checkin-error">Check-in could not be completed. Review the details and try again.</p>}</Card>{created && <Modal title="Device checked in" onClose={() => setLocation('/admin/charging')}><p className="text-sm text-muted-foreground">Keep this claim reference with the customer until collection.</p><div className="mt-5 rounded-md bg-muted/50 p-4"><p className="font-mono text-lg text-primary">{created.session.publicSessionId}</p><p className="mt-1 text-xs text-muted-foreground">Bay B-{String(created.session.slotNumber).padStart(2, '0')} · receipt {created.receipt.receiptNumber}</p></div><div className="mt-5 flex gap-3"><Link href="/admin/receipts" className="inline-flex min-h-11 flex-1 items-center justify-center rounded-md border border-border text-xs font-bold uppercase tracking-wider">View receipt</Link><Button className="flex-1" onClick={() => setLocation('/admin/charging')}>Back to floor</Button></div></Modal>}</>;
}
function Field({ label, value, onChange, test, type = 'text' }: { label: string; value: string; onChange: (v: string) => void; test: string; type?: string }) { return <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">{label}<input required type={type} value={value} onChange={e => onChange(e.target.value)} className="mt-2 h-11 w-full rounded-md border border-input bg-muted/50 px-3 text-sm text-foreground outline-none focus:border-primary" data-testid={test} /></label>; }
function SelectField({ label, value, onChange, options, test }: { label: string; value: string; onChange: (v: string) => void; options: string[]; test: string }) { return <label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">{label}<select value={value} onChange={e => onChange(e.target.value)} className="mt-2 h-11 w-full rounded-md border border-input bg-muted/50 px-3 text-sm text-foreground outline-none focus:border-primary" data-testid={test}>{options.map(o => <option key={o} value={o}>{o.replace('-', ' ')}</option>)}</select></label>; }

function Workspace() {
  const q = useListWorkspaceBookings({ query: { queryKey: getListWorkspaceBookingsQueryKey() } }); const summary = useGetDashboardSummary({ query: { queryKey: getGetDashboardSummaryQueryKey() } }); const qc = useQueryClient(); const checkIn = useCheckInWorkspaceBooking(); const checkOut = useCheckOutWorkspaceBooking(); const register = useRegisterWorkspaceBooking(); const [show, setShow] = useState(false); const [completed, setCompleted] = useState<{ receipt?: Receipt | null; invite?: string | null } | null>(null); const [form, setForm] = useState({ customerName: '', phone: '', email: '', amount: '1000', deviceType: 'laptop', paymentMethod: 'cash', whatsappOptIn: false });
  const mutateDone = () => Promise.all([qc.invalidateQueries({ queryKey: getListWorkspaceBookingsQueryKey() }), qc.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }), qc.invalidateQueries({ queryKey: getListTransactionsQueryKey() }), qc.invalidateQueries({ queryKey: getListReceiptsQueryKey() }), qc.invalidateQueries({ queryKey: getListHistoryQueryKey() })]);
  const full = summary.data ? summary.data.workspace.available <= 0 : false;
  const occupied = summary.data?.workspace.occupied ?? q.data?.filter(b => b.status === 'checked-in').length ?? 0;
  const capacity = summary.data?.workspace.capacity ?? 0;
  return <><PageHead eyebrow="Shared desk floor" title="Workspace" description="A clear view of who is checked in, who is expected, and which desks are available." action={<Button disabled={full} onClick={() => setShow(true)} data-testid="button-new-booking"><Plus size={16} /> {full ? 'Workspace full' : 'Register visitor'}</Button>} />{full && <p className="-mt-4 mb-6 rounded-md border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">Workspace capacity reached. 0 spaces available.</p>}<div className="mb-7 grid gap-4 sm:grid-cols-3"><CapacityCard label="Occupied now" value={occupied} icon={BriefcaseBusiness} accent="teal" /><CapacityCard label="Capacity" value={capacity} icon={Store} /><CapacityCard label="Available" value={summary.data?.workspace.available ?? Math.max(0, capacity - occupied)} icon={Check} /></div>{summary.data && <Card className="mb-7 p-5"><CapacityBattery label="Workspace capacity" current={summary.data.workspace.occupied} maximum={summary.data.workspace.capacity} /></Card>}<Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead><tr className="border-b border-border bg-muted/30 font-mono text-[10px] uppercase tracking-widest text-muted-foreground"><th className="px-5 py-4">Visitor</th><th>Device</th><th>Time in</th><th>Status</th><th className="px-5">Action</th></tr></thead><tbody><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(b => <tr key={b.id} className="border-b border-border last:border-0" data-testid={`row-workspace-${b.id}`}><td className="px-5 py-4"><p className="font-semibold">{b.customerName}</p><p className="font-mono text-[10px] text-muted-foreground">{b.phone ?? 'No phone'} · {money(b.amount)}</p></td><td className="font-mono text-xs text-muted-foreground">{b.deviceInfo?.type ?? '—'}</td><td className="font-mono text-xs text-muted-foreground">{dateTime(b.timeIn ?? b.createdAt)}</td><td><Status tone={b.status === 'checked-in' ? 'good' : b.status === 'cancelled' ? 'bad' : 'neutral'}>{b.status}</Status></td><td className="px-5">{b.status === 'registered' ? <Button className="min-h-9 px-3 text-[10px]" disabled={checkIn.isPending} onClick={() => checkIn.mutate({ id: b.id }, { onSuccess: () => { void mutateDone(); toast.success('Workspace visitor checked in.'); }, onError: () => toast.error('Could not check this visitor in.') })} data-testid={`button-workspace-checkin-${b.id}`}>Check in</Button> : b.status === 'checked-in' ? <Button variant="ghost" className="min-h-9 px-3 text-[10px]" disabled={checkOut.isPending} onClick={() => { if (!window.confirm(`Check out ${b.customerName}? This releases their workspace seat.`)) return; checkOut.mutate({ id: b.id }, { onSuccess: () => { void mutateDone(); toast.success('Workspace seat released.'); }, onError: () => toast.error('Could not check this visitor out.') }); }} data-testid={`button-workspace-checkout-${b.id}`}>Check out</Button> : <span className="text-xs text-muted-foreground">Complete</span>}</td></tr>)}</QueryState></tbody></table></div></Card>{show && <Modal title="Register visitor" onClose={() => setShow(false)}><div className="space-y-4 pt-5"><Field label="Customer name" value={form.customerName} onChange={v => setForm({ ...form, customerName: v })} test="input-workspace-name" /><Field label="Phone number" value={form.phone} onChange={v => setForm({ ...form, phone: v })} test="input-workspace-phone" /><Field label="Email (optional)" type="email" value={form.email} onChange={v => setForm({ ...form, email: v })} test="input-workspace-email" /><Field label="Amount" type="number" value={form.amount} onChange={v => setForm({ ...form, amount: v })} test="input-workspace-amount" /><SelectField label="Payment method" value={form.paymentMethod} onChange={v => setForm({ ...form, paymentMethod: v })} options={['cash', 'transfer', 'card', 'other']} test="select-workspace-payment" /><SelectField label="Device" value={form.deviceType} onChange={v => setForm({ ...form, deviceType: v })} options={['laptop', 'phone', 'tablet', 'other']} test="select-workspace-device" /><label className="flex items-center gap-3 text-sm"><input type="checkbox" checked={form.whatsappOptIn} onChange={e => setForm({ ...form, whatsappOptIn: e.target.checked })} data-testid="input-workspace-whatsapp" />I would like the SANFAANI Workspace WhatsApp invite.</label><Button className="w-full" disabled={register.isPending || full || !form.customerName || !form.phone || Number(form.amount) < 0} onClick={() => register.mutate({ data: { customerName: form.customerName, phone: form.phone, email: form.email || undefined, amount: Number(form.amount), paymentMethod: form.paymentMethod as 'cash' | 'transfer' | 'card' | 'other', deviceInfo: { type: form.deviceType }, whatsappOptIn: form.whatsappOptIn } }, { onSuccess: (result) => { setShow(false); setCompleted({ receipt: result.receipt, invite: result.whatsappGroupInviteUrl }); void mutateDone(); toast.success('Workspace visitor registered.'); }, onError: () => toast.error(full ? 'Workspace capacity reached.' : 'Could not register this visitor.') })} data-testid="button-submit-workspace">{register.isPending ? 'Registering…' : 'Register visitor'}</Button></div></Modal>}{completed && <Modal title="Visitor registered" onClose={() => setCompleted(null)}><p className="text-sm text-muted-foreground">The booking, ledger entry, and receipt have been saved.</p>{completed.receipt && <p className="mt-4 rounded-md bg-muted/50 p-3 font-mono text-sm">Receipt {completed.receipt.receiptNumber}</p>}{completed.invite && form.whatsappOptIn && <a href={completed.invite} target="_blank" rel="noreferrer" className="mt-4 inline-flex min-h-11 w-full items-center justify-center rounded-md border border-border text-xs font-bold uppercase tracking-wider" data-testid="link-workspace-whatsapp">Join SANFAANI Workspace WhatsApp Group</a>}<Button className="mt-4 w-full" onClick={() => setCompleted(null)}>Done</Button></Modal>}</>;
}

function Inventory() {
  const [search, setSearch] = useState(''); const q = useListProducts(search ? { search } : undefined, { query: { queryKey: getListProductsQueryKey(search ? { search } : undefined) } }); const create = useCreateProduct(); const update = useUpdateProduct(); const adjust = useAdjustProductStock(); const qc = useQueryClient(); const { profile } = useAuth(); const admin = profile?.role === 'admin'; const [show, setShow] = useState(false); const [editing, setEditing] = useState<Product | null>(null); const [adjusting, setAdjusting] = useState<Product | null>(null); const [form, setForm] = useState({ sku: '', name: '', category: 'accessories', costPrice: '0', sellingPrice: '0', quantityOnHand: '0', reorderThreshold: '3' }); const [adjustment, setAdjustment] = useState({ quantity: '', type: 'restock', reason: '', note: '' });
  const refreshed = () => Promise.all([qc.invalidateQueries({ queryKey: getListProductsQueryKey() }), qc.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() })]);
  const stockStatus = (product: Product) => !product.active ? <Status tone="neutral">Inactive</Status> : product.quantityOnHand === 0 ? <Status tone="bad">Out of stock</Status> : product.quantityOnHand <= product.reorderThreshold ? <Status tone="warn">Low stock</Status> : <Status tone="good">Healthy</Status>;
  return <><PageHead eyebrow="Stock control" title="Inventory" description="Know what is on the shelf before the next sale." action={admin ? <Button onClick={() => setShow(true)} data-testid="button-new-product"><Plus size={16} /> Add product</Button> : undefined} /><div className="mb-6 flex flex-col gap-3 sm:flex-row"><label className="relative max-w-md flex-1"><Search className="absolute left-3 top-3.5 text-muted-foreground" size={16} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search SKU or product name" className="h-11 w-full rounded-md border border-input bg-card pl-10 pr-3 text-sm outline-none focus:border-primary" data-testid="input-search-products" /></label><Button variant="ghost" onClick={() => setSearch('')} data-testid="button-clear-product-search">Clear</Button></div><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[950px] text-left"><thead><tr className="border-b border-border bg-muted/30 font-mono text-[10px] uppercase tracking-widest text-muted-foreground"><th className="px-5 py-4">Product</th><th>Category</th><th>Cost</th><th>Price</th><th>On hand</th><th>State</th>{admin && <th className="px-5">Actions</th>}</tr></thead><tbody><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(p => <tr key={p.id} className="border-b border-border last:border-0" data-testid={`row-product-${p.id}`}><td className="px-5 py-4"><p className="font-semibold">{p.name}</p><p className="font-mono text-[10px] text-muted-foreground">{p.sku}</p></td><td className="text-sm text-muted-foreground">{p.category}</td><td className="font-mono text-sm">{money(p.costPrice)}</td><td className="font-mono text-sm">{money(p.sellingPrice)}</td><td className={`font-mono text-sm ${p.quantityOnHand <= p.reorderThreshold ? 'text-primary' : ''}`}>{p.quantityOnHand}</td><td>{stockStatus(p)}</td>{admin && <td className="flex gap-2 px-5 py-3"><Button variant="ghost" className="min-h-9 px-3 text-[10px]" onClick={() => setEditing(p)} data-testid={`button-edit-product-${p.id}`}>Edit</Button><Button variant="ghost" className="min-h-9 px-3 text-[10px]" onClick={() => { setAdjusting(p); setAdjustment({ quantity: '', type: 'restock', reason: '', note: '' }); }} data-testid={`button-adjust-product-${p.id}`}>Adjust</Button></td>}</tr>)}</QueryState></tbody></table></div></Card>{show && <Modal title="Add product" onClose={() => setShow(false)}><div className="grid gap-4 pt-5 sm:grid-cols-2"><Field label="SKU" value={form.sku} onChange={v => setForm({ ...form, sku: v })} test="input-product-sku" /><Field label="Product name" value={form.name} onChange={v => setForm({ ...form, name: v })} test="input-product-name" /><Field label="Category" value={form.category} onChange={v => setForm({ ...form, category: v })} test="input-product-category" /><Field label="Cost price" type="number" value={form.costPrice} onChange={v => setForm({ ...form, costPrice: v })} test="input-product-cost" /><Field label="Selling price" type="number" value={form.sellingPrice} onChange={v => setForm({ ...form, sellingPrice: v })} test="input-product-price" /><Field label="Opening stock" type="number" value={form.quantityOnHand} onChange={v => setForm({ ...form, quantityOnHand: v })} test="input-product-quantity" /><Field label="Reorder threshold" type="number" value={form.reorderThreshold} onChange={v => setForm({ ...form, reorderThreshold: v })} test="input-product-threshold" /></div><Button className="mt-5 w-full" disabled={create.isPending || !form.sku || !form.name || Number(form.quantityOnHand) < 0} onClick={() => create.mutate({ data: { ...form, costPrice: Number(form.costPrice), sellingPrice: Number(form.sellingPrice), quantityOnHand: Number(form.quantityOnHand), reorderThreshold: Number(form.reorderThreshold) } }, { onSuccess: () => { setShow(false); void refreshed(); toast.success('Product created.'); }, onError: () => toast.error('Could not create this product. Check the SKU and details.') })} data-testid="button-submit-product">{create.isPending ? 'Saving…' : 'Save product'}</Button></Modal>}{editing && <Modal title={`Edit ${editing.name}`} onClose={() => setEditing(null)}><div className="grid gap-4 pt-5"><Field label="Product name" value={editing.name} onChange={v => setEditing({ ...editing, name: v })} test="input-edit-product-name" /><Field label="Category" value={editing.category} onChange={v => setEditing({ ...editing, category: v })} test="input-edit-product-category" /><Field label="Cost price" type="number" value={String(editing.costPrice)} onChange={v => setEditing({ ...editing, costPrice: Number(v) })} test="input-edit-product-cost" /><Field label="Selling price" type="number" value={String(editing.sellingPrice)} onChange={v => setEditing({ ...editing, sellingPrice: Number(v) })} test="input-edit-product-price" /><Field label="Reorder threshold" type="number" value={String(editing.reorderThreshold)} onChange={v => setEditing({ ...editing, reorderThreshold: Number(v) })} test="input-edit-product-threshold" /><label className="flex items-center gap-3 text-sm"><input type="checkbox" checked={editing.active} onChange={e => setEditing({ ...editing, active: e.target.checked })} data-testid="input-edit-product-active" />Product is active for sales</label></div><Button className="mt-5 w-full" disabled={update.isPending || !editing.name || Number(editing.reorderThreshold) < 0} onClick={() => update.mutate({ id: editing.id, data: { name: editing.name, category: editing.category, costPrice: editing.costPrice, sellingPrice: editing.sellingPrice, reorderThreshold: editing.reorderThreshold, active: editing.active } }, { onSuccess: () => { setEditing(null); void refreshed(); toast.success('Product updated.'); }, onError: () => toast.error('Could not update this product.') })} data-testid="button-save-product-edit">{update.isPending ? 'Saving…' : 'Save changes'}</Button></Modal>}{adjusting && <Modal title={`Adjust ${adjusting.name}`} onClose={() => setAdjusting(null)}><p className="text-sm text-muted-foreground">Current stock: {adjusting.quantityOnHand}. Use a positive quantity to add stock and a negative quantity for a write-off or correction.</p><div className="space-y-4 pt-5"><SelectField label="Adjustment type" value={adjustment.type} onChange={v => setAdjustment({ ...adjustment, type: v })} options={['restock', 'write-off', 'correction', 'return', 'other']} test="select-stock-adjustment-type" /><Field label="Quantity change" type="number" value={adjustment.quantity} onChange={v => setAdjustment({ ...adjustment, quantity: v })} test="input-stock-adjustment-quantity" /><Field label="Reason" value={adjustment.reason} onChange={v => setAdjustment({ ...adjustment, reason: v })} test="input-stock-adjustment-reason" /><Field label="Note (optional)" value={adjustment.note} onChange={v => setAdjustment({ ...adjustment, note: v })} test="input-stock-adjustment-note" /></div><Button variant={adjustment.type === 'write-off' ? 'danger' : 'primary'} className="mt-5 w-full" disabled={adjust.isPending || !adjustment.reason || !Number(adjustment.quantity)} onClick={() => { if (adjustment.type === 'write-off' && !window.confirm('Confirm this stock write-off. This will be preserved in inventory history.')) return; adjust.mutate({ id: adjusting.id, data: { quantity: Number(adjustment.quantity), type: adjustment.type as 'restock' | 'write-off' | 'correction' | 'return' | 'other', reason: adjustment.reason, note: adjustment.note || undefined } }, { onSuccess: () => { setAdjusting(null); void refreshed(); toast.success('Stock adjustment recorded.'); }, onError: () => toast.error('This adjustment would leave stock below zero or could not be saved.') }); }} data-testid="button-submit-stock-adjustment">{adjust.isPending ? 'Saving…' : 'Record adjustment'}</Button></Modal>}</>;
}

function Sales() {
  const products = useListProducts(undefined, { query: { queryKey: getListProductsQueryKey() } }); const customers = useListCustomers(undefined, { query: { queryKey: getListCustomersQueryKey() } }); const sale = useCreateSale(); const qc = useQueryClient(); const [cart, setCart] = useState<Record<string, number>>({}); const [customerId, setCustomerId] = useState(''); const [paymentMethod, setPaymentMethod] = useState('cash'); const [receipt, setReceipt] = useState<Receipt | null>(null); const items = products.data?.filter(p => cart[p.id]) ?? []; const total = items.reduce((sum, p) => sum + p.sellingPrice * cart[p.id], 0);
  const setQuantity = (product: Product, nextQuantity: number) => { if (nextQuantity <= 0) { const next = { ...cart }; delete next[product.id]; setCart(next); return; } if (nextQuantity > product.quantityOnHand) { toast.error(`Only ${product.quantityOnHand} ${product.name} available.`); return; } setCart({ ...cart, [product.id]: nextQuantity }); };
  const invalidate = () => Promise.all([qc.invalidateQueries({ queryKey: getListProductsQueryKey() }), qc.invalidateQueries({ queryKey: getListSalesQueryKey() }), qc.invalidateQueries({ queryKey: getListReceiptsQueryKey() }), qc.invalidateQueries({ queryKey: getListTransactionsQueryKey() }), qc.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }), qc.invalidateQueries({ queryKey: getListHistoryQueryKey() })]);
  return <><PageHead eyebrow="Point of sale" title="Quick sale" description="Build a multi-item basket and close it in one clean handoff." /><div className="grid gap-7 xl:grid-cols-[1.2fr_.8fr]"><Card className="p-5"><SectionTitle>Available products</SectionTitle><QueryState loading={products.isLoading} error={products.isError} empty={!products.data?.length}><div className="grid gap-3 sm:grid-cols-2">{products.data?.filter(p => p.active && p.quantityOnHand > 0).map(p => <button key={p.id} onClick={() => setQuantity(p, (cart[p.id] ?? 0) + 1)} disabled={(cart[p.id] ?? 0) >= p.quantityOnHand} className="flex min-h-20 items-center justify-between rounded-md border border-border bg-muted/20 p-4 text-left transition hover:border-primary hover:bg-primary/5 disabled:cursor-not-allowed disabled:opacity-50" data-testid={`button-add-sale-${p.id}`}><div><p className="font-semibold">{p.name}</p><p className="font-mono text-[10px] text-muted-foreground">{p.quantityOnHand} available · {p.sku}</p></div><span className="font-mono text-sm text-primary">{money(p.sellingPrice)}</span></button>)}</div></QueryState></Card><Card className="p-5"><SectionTitle>Current basket</SectionTitle>{!items.length ? <div className="grid min-h-40 place-items-center rounded-md border border-dashed border-border text-center text-sm text-muted-foreground"><ShoppingCart className="mb-2" />Select a product to begin</div> : <div className="space-y-3">{items.map(p => <div key={p.id} className="flex items-center gap-3 border-b border-border pb-3"><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{p.name}</p><div className="mt-2 flex items-center gap-2"><Button variant="ghost" className="min-h-8 px-2 text-xs" aria-label={`Decrease ${p.name}`} onClick={() => setQuantity(p, cart[p.id] - 1)}>−</Button><span className="min-w-6 text-center font-mono text-xs">{cart[p.id]}</span><Button variant="ghost" className="min-h-8 px-2 text-xs" aria-label={`Increase ${p.name}`} disabled={cart[p.id] >= p.quantityOnHand} onClick={() => setQuantity(p, cart[p.id] + 1)}>+</Button><span className="font-mono text-[10px] text-muted-foreground">× {money(p.sellingPrice)}</span></div></div><span className="font-mono text-sm">{money(p.sellingPrice * cart[p.id])}</span><button onClick={() => setQuantity(p, 0)} className="text-muted-foreground hover:text-destructive" data-testid={`button-remove-sale-${p.id}`} aria-label={`Remove ${p.name}`}><X size={15} /></button></div>)}<div className="border-t border-border pt-4"><label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Customer (optional)<select value={customerId} onChange={e => setCustomerId(e.target.value)} className="mt-2 h-11 w-full rounded-md border border-input bg-muted/50 px-3 text-sm" data-testid="select-sale-customer"><option value="">Walk-in customer</option>{customers.data?.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="mt-4 block text-xs font-semibold uppercase tracking-wider text-muted-foreground">Payment<select value={paymentMethod} onChange={e => setPaymentMethod(e.target.value)} className="mt-2 h-11 w-full rounded-md border border-input bg-muted/50 px-3 text-sm" data-testid="select-sale-payment"><option value="cash">Cash</option><option value="transfer">Transfer</option><option value="card">Card</option><option value="other">Other</option></select></label><div className="mt-5 flex items-end justify-between"><span className="text-sm text-muted-foreground">Total</span><span className="font-mono text-2xl text-primary">{money(total)}</span></div><Button className="mt-5 w-full" disabled={sale.isPending || !items.length} onClick={() => sale.mutate({ data: { customerId: customerId || undefined, items: items.map(p => ({ productId: p.id, quantity: cart[p.id] })), paymentMethod: paymentMethod as 'cash' | 'transfer' | 'card' | 'other' } as SaleInput }, { onSuccess: (result) => { setCart({}); setReceipt(result.receipt); void invalidate(); toast.success('Sale completed and receipt created.'); }, onError: () => toast.error('Sale was not completed. Check stock and try again.') })} data-testid="button-complete-sale"><CreditCard size={16} />{sale.isPending ? 'Processing…' : 'Complete sale'}</Button></div></div>}</Card></div>{receipt && <Modal title="Sale complete" onClose={() => setReceipt(null)}><p className="text-sm text-muted-foreground">Receipt {receipt.receiptNumber} has been created for {money(receipt.total)}.</p><div className="mt-5 flex gap-3"><Link href="/admin/receipts" className="inline-flex min-h-11 flex-1 items-center justify-center rounded-md border border-border text-xs font-bold uppercase tracking-wider">View receipts</Link><Button className="flex-1" onClick={() => setReceipt(null)}>New sale</Button></div></Modal>}</>;
}

function Customers() {
  const [search, setSearch] = useState(''); const q = useListCustomers(search ? { search } : undefined, { query: { queryKey: getListCustomersQueryKey(search ? { search } : undefined) } }); const create = useCreateCustomer(); const qc = useQueryClient(); const [show, setShow] = useState(false); const [form, setForm] = useState({ name: '', phone: '', email: '', whatsappOptIn: false });
  return <><PageHead eyebrow="Customer register" title="Customers" description="Keep the customer record useful, current, and easy to find." action={<Button onClick={() => setShow(true)} data-testid="button-new-customer"><Plus size={16} /> Add customer</Button>} /><div className="mb-6 max-w-md"><label className="relative block"><Search className="absolute left-3 top-3.5 text-muted-foreground" size={16} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by name, phone, or email" className="h-11 w-full rounded-md border border-input bg-card pl-10 pr-3 text-sm outline-none focus:border-primary" data-testid="input-search-customers" /></label></div><Card className="overflow-hidden"><div className="divide-y divide-border"><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(c => <div key={c.id} className="flex items-center gap-4 p-5" data-testid={`row-customer-${c.id}`}><span className="grid h-10 w-10 place-items-center rounded-full bg-secondary/20 font-mono text-sm text-secondary-foreground">{c.name.split(' ').map(x => x[0]).slice(0, 2).join('')}</span><div className="min-w-0 flex-1"><p className="font-semibold">{c.name}</p><p className="font-mono text-[10px] text-muted-foreground">{c.phone ?? 'No phone'} {c.email ? `· ${c.email}` : ''}</p></div><Status tone={c.whatsappOptIn ? 'good' : 'neutral'}>{c.whatsappOptIn ? 'WhatsApp on' : 'No WhatsApp'}</Status></div>)}</QueryState></div></Card>{show && <Modal title="Add customer" onClose={() => setShow(false)}><div className="space-y-4 pt-5"><Field label="Full name" value={form.name} onChange={v => setForm({ ...form, name: v })} test="input-customer-full-name" /><Field label="Phone number" value={form.phone} onChange={v => setForm({ ...form, phone: v })} test="input-customer-phone" /><Field label="Email (optional)" value={form.email} onChange={v => setForm({ ...form, email: v })} test="input-customer-email" type="email" /><label className="flex items-center gap-3 text-sm"><input type="checkbox" checked={form.whatsappOptIn} onChange={e => setForm({ ...form, whatsappOptIn: e.target.checked })} />Customer consents to WhatsApp updates</label><Button className="w-full" disabled={create.isPending || form.name.length < 2 || (form.phone.length > 0 && form.phone.length < 7)} onClick={() => create.mutate({ data: { name: form.name, phone: form.phone, email: form.email, whatsappOptIn: form.whatsappOptIn } }, { onSuccess: () => { setShow(false); setForm({ name: '', phone: '', email: '', whatsappOptIn: false }); void qc.invalidateQueries({ queryKey: getListCustomersQueryKey() }); toast.success('Customer saved.'); }, onError: () => toast.error('Could not save this customer. Check for a duplicate email.') })} data-testid="button-submit-customer">{create.isPending ? 'Saving…' : 'Save customer'}</Button></div></Modal>}</>;
}

function Transactions() { const [period, setPeriod] = useState<'today' | 'yesterday' | 'week' | 'month'>('month'); const [page, setPage] = useState(1); const params = { period, page, limit: 50 }; const q = useListTransactions(params, { query: { queryKey: getListTransactionsQueryKey(params), staleTime: 60_000 } }); return <><PageHead eyebrow="Bookkeeping" title="Transactions" description="A central ledger for every income and expense recorded through operations." action={<select value={period} onChange={e => { setPeriod(e.target.value as typeof period); setPage(1); }} className="h-11 rounded-md border border-input bg-card px-3 text-sm" data-testid="select-transaction-period"><option value="today">Today</option><option value="yesterday">Yesterday</option><option value="week">This week</option><option value="month">This month</option></select>} /><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[750px] text-left"><thead><tr className="border-b border-border bg-muted/30 font-mono text-[10px] uppercase tracking-widest text-muted-foreground"><th className="px-5 py-4">Description</th><th>Type</th><th>Method</th><th>Date</th><th className="px-5 text-right">Amount</th></tr></thead><tbody><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(t => <tr key={t.id} className="border-b border-border last:border-0" data-testid={`row-transaction-${t.id}`}><td className="px-5 py-4 text-sm">{t.description}</td><td><Status tone={t.direction === 'income' ? 'good' : 'bad'}>{t.type}</Status></td><td className="text-xs text-muted-foreground">{t.paymentMethod}</td><td className="font-mono text-xs text-muted-foreground">{dateTime(t.createdAt)}</td><td className={`px-5 text-right font-mono ${t.direction === 'income' ? 'text-[#75d6bd]' : 'text-destructive'}`}>{t.direction === 'income' ? '+' : '-'}{money(t.amount)}</td></tr>)}</QueryState></tbody></table></div></Card><Pager page={page} canNext={(q.data?.length ?? 0) === 50} onPage={setPage} /></>; }
function Receipts() { const [page, setPage] = useState(1); const params = { page, limit: 50 }; const q = useListReceipts(params, { query: { queryKey: getListReceiptsQueryKey(params), staleTime: 60_000 } }); return <><PageHead eyebrow="Proof of service" title="Receipts" description="Open, print, or export a structured record of every service." /><Card className="overflow-hidden"><div className="divide-y divide-border"><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(r => <div key={r.id} className="flex flex-wrap items-center gap-4 p-5" data-testid={`row-receipt-${r.id}`}><span className="grid h-10 w-10 place-items-center rounded-md bg-primary/10 text-primary"><ReceiptText size={18} /></span><div className="min-w-[180px] flex-1"><p className="font-mono text-sm">{r.receiptNumber}</p><p className="text-xs text-muted-foreground">{r.customerName ?? 'Walk-in'} · {r.type}</p></div><span className="font-mono text-sm">{money(r.total)}</span><span className="text-xs text-muted-foreground">{dateTime(r.generatedAt)}</span><Link href={`/admin/receipts/${r.id}`} className="inline-flex min-h-9 items-center gap-2 rounded-md border border-border px-3 text-[10px] font-bold uppercase tracking-wider" data-testid={`link-receipt-${r.id}`}><ReceiptText size={14} /> View</Link></div>)}</QueryState></div></Card><Pager page={page} canNext={(q.data?.length ?? 0) === 50} onPage={setPage} /></>; }
function Pager({ page, canNext, onPage }: { page: number; canNext: boolean; onPage: (page: number) => void }) { return <div className="mt-4 flex items-center justify-between"><span className="font-mono text-[10px] text-muted-foreground">Page {page}</span><div className="flex gap-2"><Button variant="ghost" className="min-h-9 px-3 text-[10px]" disabled={page === 1} onClick={() => onPage(page - 1)}>Previous</Button><Button variant="ghost" className="min-h-9 px-3 text-[10px]" disabled={!canNext} onClick={() => onPage(page + 1)}>Next</Button></div></div>; }
function HistoryRecordRow({ entry }: { entry: HistoryRecord }) { const record = entry.record; const title = 'publicSessionId' in record ? `${record.customerName} · ${record.publicSessionId}` : entry.kind === 'workspace' && 'customerName' in record ? `${record.customerName} · workspace ${record.status}` : 'total' in record ? `Sale · ${money(record.total)}` : 'description' in record ? record.description : 'Transaction'; const amount = 'total' in record ? record.total : 'amount' in record ? record.amount : undefined; return <div className="flex items-center gap-4 border-b border-border py-4 last:border-0"><Status tone={entry.kind === 'transactions' ? 'good' : 'neutral'}>{entry.kind}</Status><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{title}</p><p className="font-mono text-[10px] text-muted-foreground">{dateTime(entry.timestamp)}</p></div>{typeof amount === 'number' && <span className="font-mono text-sm">{money(amount)}</span>}</div>; }
function HistoryPage() { const [date, setDate] = useState(new Date().toISOString().slice(0, 10)); const [type, setType] = useState<'all' | 'charging' | 'workspace' | 'sales' | 'transactions'>('all'); const [page, setPage] = useState(1); const params = { date, type, page, limit: 25 }; const q = useListHistory(params, { query: { queryKey: getListHistoryQueryKey(params) } }); const selectType = (next: typeof type) => { setType(next); setPage(1); }; return <><PageHead eyebrow="Audit trail" title="Daily history" description="Review what moved through the floor, by the business-local date." action={<input type="date" value={date} onChange={e => { setDate(e.target.value); setPage(1); }} className="h-11 rounded-md border border-input bg-card px-3 font-mono text-xs" data-testid="input-history-date" />} />{q.data && <div className="mb-6 grid gap-4 sm:grid-cols-4">{[['REVENUE', money(q.data.summary.revenue)], ['CHARGING', q.data.summary.chargingCount], ['WORKSPACE', q.data.summary.workspaceCount], ['SALES', q.data.summary.salesCount]].map(([l, v]) => <Card key={l as string} className="p-5"><p className="font-mono text-[10px] text-muted-foreground">{l as string}</p><p className="mt-3 font-mono text-2xl">{v as string | number}</p></Card>)}</div>}<Card className="p-5"><div className="mb-5 flex flex-wrap gap-2" role="tablist" aria-label="History module"><>{(['all', 'charging', 'workspace', 'sales', 'transactions'] as const).map(tab => <button key={tab} role="tab" aria-selected={type === tab} onClick={() => selectType(tab)} className={`rounded-md px-3 py-2 text-[10px] font-bold uppercase tracking-wider ${type === tab ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:text-foreground'}`} data-testid={`tab-history-${tab}`}>{tab}</button>)}</></div><SectionTitle>{type === 'all' ? 'All recorded activity' : `${type} activity`}</SectionTitle><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.records.length}>{q.data?.records.map((entry, index) => <HistoryRecordRow key={`${entry.kind}-${entry.timestamp}-${index}`} entry={entry} />)}</QueryState>{q.data && q.data.pagination.pages > 1 && <div className="mt-5 flex items-center justify-between border-t border-border pt-4"><p className="font-mono text-[10px] text-muted-foreground">Page {q.data.pagination.page} of {q.data.pagination.pages}</p><div className="flex gap-2"><Button variant="ghost" className="min-h-9 px-3 text-[10px]" disabled={page <= 1} onClick={() => setPage(page - 1)}>Previous</Button><Button variant="ghost" className="min-h-9 px-3 text-[10px]" disabled={page >= q.data.pagination.pages} onClick={() => setPage(page + 1)}>Next</Button></div></div>}</Card></>; }

function SettingsPage() {
  const q = useGetSettings({ query: { queryKey: getGetSettingsQueryKey() } }); const update = useUpdateSettings(); const qc = useQueryClient(); const [form, setForm] = useState<SettingsInput | null>(null);
  useEffect(() => { if (q.data) setForm({ businessName: q.data.businessName, businessAddress: q.data.businessAddress ?? '', phone: q.data.phone ?? '', currency: q.data.currency, chargingCapacity: q.data.chargingCapacity, workspaceCapacity: q.data.workspaceCapacity, defaultChargingPrice: q.data.defaultChargingPrice, defaultWorkspacePrice: q.data.defaultWorkspacePrice, whatsappGroupInviteUrl: q.data.whatsappGroupInviteUrl ?? '', businessTimezone: q.data.businessTimezone, receiptFooter: q.data.receiptFooter ?? '' }); }, [q.data?.id]);
  if (q.isLoading || !form) return <LoadingState />;
  if (q.isError) return <QueryState error={q.error}> </QueryState>;
  const set = <K extends keyof SettingsInput>(key: K, value: SettingsInput[K]) => setForm((current) => current ? { ...current, [key]: value } : current);
  return <><PageHead eyebrow="Administrator control" title="Settings" description="Business-wide operational settings. Capacity cannot be reduced below current occupancy." /><Card className="max-w-4xl p-6 md:p-8"><div className="grid gap-5 md:grid-cols-2"><Field label="Business name" value={form.businessName} onChange={v => set('businessName', v)} test="input-settings-name" /><Field label="Business phone" value={form.phone ?? ''} onChange={v => set('phone', v)} test="input-settings-phone" /><Field label="Business address" value={form.businessAddress ?? ''} onChange={v => set('businessAddress', v)} test="input-settings-address" /><Field label="Currency" value={form.currency} onChange={v => set('currency', v.toUpperCase())} test="input-settings-currency" /><Field label="Charging capacity" type="number" value={String(form.chargingCapacity)} onChange={v => set('chargingCapacity', Number(v))} test="input-settings-charging-capacity" /><Field label="Workspace capacity" type="number" value={String(form.workspaceCapacity)} onChange={v => set('workspaceCapacity', Number(v))} test="input-settings-workspace-capacity" /><Field label="Default charging price" type="number" value={String(form.defaultChargingPrice)} onChange={v => set('defaultChargingPrice', Number(v))} test="input-settings-charging-price" /><Field label="Default workspace price" type="number" value={String(form.defaultWorkspacePrice)} onChange={v => set('defaultWorkspacePrice', Number(v))} test="input-settings-workspace-price" /><Field label="Business timezone" value={form.businessTimezone} onChange={v => set('businessTimezone', v)} test="input-settings-timezone" /><Field label="WhatsApp group invite URL" value={form.whatsappGroupInviteUrl ?? ''} onChange={v => set('whatsappGroupInviteUrl', v)} test="input-settings-whatsapp" /></div><label className="mt-5 block text-xs font-semibold uppercase tracking-wider text-muted-foreground">Receipt footer<textarea value={form.receiptFooter ?? ''} onChange={e => set('receiptFooter', e.target.value)} className="mt-2 min-h-24 w-full rounded-md border border-input bg-muted/50 p-3 text-sm text-foreground outline-none focus:border-primary" data-testid="input-settings-receipt-footer" /></label><Button className="mt-7" disabled={update.isPending || form.chargingCapacity < 1 || form.workspaceCapacity < 1 || form.currency.length !== 3} onClick={() => update.mutate({ data: form }, { onSuccess: () => { void Promise.all([qc.invalidateQueries({ queryKey: getGetSettingsQueryKey() }), qc.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() })]); toast.success('Settings saved. Operational capacity has been refreshed.'); }, onError: () => toast.error('Could not update settings. Capacity may be below current occupancy.') })} data-testid="button-save-settings">{update.isPending ? 'Saving…' : 'Save settings'}</Button></Card></>;
}

function StaffManagement() {
  const q = useListStaff({ query: { queryKey: getListStaffQueryKey() } }); const roleUpdate = useUpdateStaffRole(); const activeUpdate = useUpdateStaffActive(); const qc = useQueryClient(); const [pendingRole, setPendingRole] = useState<{ user: AppUser; role: 'admin' | 'staff' | 'customer' } | null>(null); const [pendingActive, setPendingActive] = useState<AppUser | null>(null); const refresh = () => qc.invalidateQueries({ queryKey: getListStaffQueryKey() });
  return <><PageHead eyebrow="Administrator control" title="Staff management" description="Manage application roles and access without deleting accounts." /><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[800px] text-left"><thead><tr className="border-b border-border bg-muted/30 font-mono text-[10px] uppercase tracking-widest text-muted-foreground"><th className="px-5 py-4">User</th><th>Role</th><th>Access</th><th>Created</th><th className="px-5">Actions</th></tr></thead><tbody><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(user => <tr key={user.appUserId} className="border-b border-border last:border-0" data-testid={`row-staff-${user.appUserId}`}><td className="px-5 py-4"><p className="font-semibold">{user.name ?? user.email}</p><p className="font-mono text-[10px] text-muted-foreground">{user.email}</p></td><td><select value={user.role} onChange={e => setPendingRole({ user, role: e.target.value as 'admin' | 'staff' | 'customer' })} className="h-9 rounded-md border border-input bg-card px-2 text-xs" data-testid={`select-staff-role-${user.appUserId}`}><option value="admin">Admin</option><option value="staff">Staff</option><option value="customer">Customer</option></select></td><td><Status tone={user.active ? 'good' : 'bad'}>{user.active ? 'Active' : 'Inactive'}</Status></td><td className="text-xs text-muted-foreground">{dateTime(user.createdAt)}</td><td className="px-5"><Button variant={user.active ? 'danger' : 'teal'} className="min-h-9 px-3 text-[10px]" onClick={() => setPendingActive(user)} data-testid={`button-staff-active-${user.appUserId}`}>{user.active ? 'Deactivate' : 'Reactivate'}</Button></td></tr>)}</QueryState></tbody></table></div></Card>{pendingRole && <Modal title="Confirm role change" onClose={() => setPendingRole(null)}><p className="text-sm text-muted-foreground">Change {pendingRole.user.email} from <strong>{pendingRole.user.role}</strong> to <strong>{pendingRole.role}</strong>? This is recorded in the audit log.</p><Button className="mt-5 w-full" disabled={roleUpdate.isPending} onClick={() => roleUpdate.mutate({ id: pendingRole.user.appUserId, data: { role: pendingRole.role } }, { onSuccess: () => { setPendingRole(null); void refresh(); toast.success('Role updated and audited.'); }, onError: () => toast.error('Could not update this role. The last active administrator must remain.') })} data-testid="button-confirm-staff-role">{roleUpdate.isPending ? 'Updating…' : 'Confirm role change'}</Button></Modal>}{pendingActive && <Modal title={pendingActive.active ? 'Deactivate account' : 'Reactivate account'} onClose={() => setPendingActive(null)}><p className="text-sm text-muted-foreground">{pendingActive.active ? `Deactivate ${pendingActive.email}? They will be blocked on their next authenticated request.` : `Reactivate ${pendingActive.email}? They can sign in again.`}</p><Button variant={pendingActive.active ? 'danger' : 'teal'} className="mt-5 w-full" disabled={activeUpdate.isPending} onClick={() => activeUpdate.mutate({ id: pendingActive.appUserId, data: { active: !pendingActive.active } }, { onSuccess: () => { setPendingActive(null); void refresh(); toast.success('Account access updated and audited.'); }, onError: () => toast.error('Could not update account access. The final active administrator cannot be deactivated.') })} data-testid="button-confirm-staff-active">{activeUpdate.isPending ? 'Saving…' : pendingActive.active ? 'Deactivate account' : 'Reactivate account'}</Button></Modal>}</>;
}

function OperationalNotifications() { const q = useListNotifications({ query: { queryKey: getListNotificationsQueryKey() } }); const markRead = useMarkNotificationRead(); const qc = useQueryClient(); return <><PageHead eyebrow="Operational updates" title="Notifications" description="Updates assigned to your application account." /><Card className="divide-y divide-border overflow-hidden"><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(notification => <button key={notification.id} disabled={notification.read || markRead.isPending} onClick={() => markRead.mutate({ id: notification.id }, { onSuccess: () => { void qc.invalidateQueries({ queryKey: getListNotificationsQueryKey() }); toast.success('Notification marked as read.'); }, onError: () => toast.error('Could not mark this notification as read.') })} className={`flex w-full gap-4 p-5 text-left disabled:cursor-default ${notification.read ? 'bg-background' : 'bg-primary/5'}`}><Bell className={notification.read ? 'text-muted-foreground' : 'text-primary'} /><div className="flex-1"><div className="flex items-center justify-between gap-3"><h2 className="font-semibold">{notification.title}</h2><Status tone={notification.read ? 'neutral' : 'good'}>{notification.read ? 'read' : 'unread'}</Status></div><p className="mt-1 text-sm text-muted-foreground">{notification.message}</p><p className="mt-2 font-mono text-[10px] text-muted-foreground">{dateTime(notification.createdAt)}</p></div></button>)}</QueryState></Card></>; }

function CustomerHome({ page = 'home' }: { page?: 'home' | 'device' | 'workspace' | 'receipts' | 'notifications' | 'profile' }) {
  const charging = useGetCustomerMyCharging();
  const workspace = useGetCustomerMyWorkspace();
  const { signOut } = useAuth();
  const [, setLocation] = useLocation();
  const customerSessions = charging.data?.recentSessions ?? [];
  const latest = charging.data?.activeSession ?? customerSessions[0];
  const logout = async () => { await signOut(); setLocation('/sign-in'); };
  const latestWorkspace = workspace.data?.[0];
  return <div className="min-h-[100dvh] bg-background"><header className="flex h-[72px] items-center justify-between border-b border-border px-5 md:px-10"><Brand /><div className="flex items-center gap-4"><span className="hidden font-mono text-[10px] uppercase tracking-widest text-muted-foreground sm:block">Customer portal</span><button onClick={() => void logout()} className="rounded-md p-2 text-muted-foreground" data-testid="button-customer-logout" aria-label="Sign out"><LogOut size={17} /></button></div></header><main className="mx-auto max-w-4xl p-5 py-10 md:p-10"><div className="mb-8 flex flex-wrap gap-2 border-b border-border pb-3">{[['home', 'Status', '/customer'], ['device', 'My device', '/customer/device'], ['workspace', 'Workspace', '/customer/workspace'], ['receipts', 'Receipts', '/customer/receipts'], ['notifications', 'Notifications', '/customer/notifications'], ['profile', 'Profile', '/customer/profile']].map(([key, label, href]) => <Link key={key} href={href} className={`rounded-md px-4 py-2 text-xs font-bold uppercase tracking-wider ${page === key ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted'}`} data-testid={`link-customer-${key}`}>{label}</Link>)}</div>{page === 'home' && <><PageHead eyebrow="Your SANFAANI visit" title="Hello, welcome back." description="Your latest operational status, in one place." /><div className="grid gap-5 md:grid-cols-2"><Card className="p-6"><QueryState loading={charging.isLoading} error={charging.isError}><div className="flex items-start gap-4"><span className="grid h-12 w-12 place-items-center rounded-md bg-secondary/20 text-secondary"><BatteryCharging /></span><div className="flex-1"><p className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">Latest device status</p><h2 className="mt-2 text-2xl font-semibold">{latest?.status ?? 'No active session'}</h2><p className="mt-1 text-sm text-muted-foreground">{latest ? `${latest.device.brand ?? latest.device.type} · Bay ${latest.slotNumber}` : 'Your charging and workspace activity will appear here.'}</p></div><Status tone={latest?.status === 'ready' ? 'good' : 'neutral'}>{latest?.status ?? 'quiet'}</Status></div></QueryState></Card><Card className="p-6"><QueryState loading={workspace.isLoading} error={workspace.isError}><p className="font-mono text-[10px] uppercase tracking-widest text-muted-foreground">Workspace</p><h2 className="mt-2 text-2xl font-semibold">{latestWorkspace?.status ?? 'No current booking'}</h2><p className="mt-1 text-sm text-muted-foreground">{latestWorkspace ? `Seat ${latestWorkspace.seatNumber ?? '—'} · ${dateTime(latestWorkspace.timeIn ?? latestWorkspace.createdAt)}` : 'Workspace bookings will appear here.'}</p></QueryState></Card></div></>}{page === 'device' && <><PageHead eyebrow="Device details" title="Your device" /><Card className="p-6"><QueryState loading={charging.isLoading} error={charging.isError} empty={!customerSessions.length}>{customerSessions.slice(0, 1).map(s => <div key={s.id} className="grid gap-5 sm:grid-cols-2"><Detail label="Claim reference" value={s.publicSessionId} /><Detail label="Device" value={`${s.device.brand ?? ''} ${s.device.model ?? s.device.type}`} /><Detail label="Bay" value={`B-${String(s.slotNumber).padStart(2, '0')}`} /><Detail label="Status" value={s.status} /><Detail label="Checked in" value={dateTime(s.timeIn)} /><Detail label="Estimated ready" value={dateTime(s.estimatedReadyAt)} /></div>)}</QueryState></Card></>}{page === 'workspace' && <CustomerWorkspace />}{page === 'receipts' && <CustomerReceipts />}{page === 'notifications' && <CustomerNotifications />}{page === 'profile' && <Suspense fallback={<LoadingState />}><CustomerProfile /></Suspense>}</main></div>;
}
function Detail({ label, value }: { label: string; value: string }) { return <div className="rounded-md bg-muted/40 p-4"><p className="font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{label}</p><p className="mt-2 text-sm font-semibold">{value}</p></div>; }
function CustomerWorkspace() { const q = useGetCustomerMyWorkspace(); return <><PageHead eyebrow="Workspace" title="Your workspace visits" /><Card className="divide-y divide-border overflow-hidden"><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(booking => <div key={booking.id} className="flex flex-wrap items-center gap-4 p-5"><BriefcaseBusiness className="text-secondary" /><div className="flex-1"><p className="font-semibold">Seat {booking.seatNumber ?? '—'}</p><p className="text-xs text-muted-foreground">{booking.deviceInfo?.type ?? 'Workspace visit'} · {dateTime(booking.timeIn ?? booking.createdAt)}</p></div><Status tone={booking.status === 'checked-in' ? 'good' : 'neutral'}>{booking.status}</Status></div>)}</QueryState></Card></>; }
function CustomerReceipts() { const [page, setPage] = useState(1); const q = useGetCustomerMyReceipts({ page, limit: 50 }); return <><PageHead eyebrow="Proof of service" title="Your receipts" /><Card className="divide-y divide-border overflow-hidden"><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(r => <Link href={`/customer/receipts/${r.id}`} key={r.id} className="flex items-center gap-4 p-5 hover:bg-muted/30"><ReceiptText className="text-primary" /><div className="flex-1"><p className="font-mono text-sm">{r.receiptNumber}</p><p className="text-xs text-muted-foreground">{r.type} · {dateTime(r.generatedAt)}</p></div><span className="font-mono">{money(r.total)}</span><ChevronRight size={16} className="text-muted-foreground" /></Link>)}</QueryState></Card><Pager page={page} canNext={(q.data?.length ?? 0) === 50} onPage={setPage} /></>; }
function CustomerNotifications() { const q = useGetCustomerMyNotifications(); const qc = useQueryClient(); const markRead = useMarkCustomerNotificationRead(); return <><PageHead eyebrow="Updates" title="Notifications" /><Suspense fallback={<LoadingState />}><NotificationControl /></Suspense><Card className="mt-5 divide-y divide-border overflow-hidden"><QueryState loading={q.isLoading} error={q.isError} empty={!q.data?.length}>{q.data?.map(notification => <button key={notification.id} disabled={notification.read || markRead.isPending} onClick={() => markRead.mutate({ id: notification.id }, { onSuccess: () => { void qc.invalidateQueries({ queryKey: getGetCustomerMyNotificationsQueryKey() }); toast.success('Notification marked as read.'); }, onError: () => toast.error('Could not update this notification.') })} className={`flex w-full gap-4 p-5 text-left disabled:cursor-default ${notification.read ? 'bg-background' : 'bg-primary/5'}`}><Bell className={notification.read ? 'text-muted-foreground' : 'text-primary'} /><div className="flex-1"><div className="flex items-center justify-between gap-3"><h2 className="font-semibold">{notification.title}</h2><Status tone={notification.read ? 'neutral' : 'good'}>{notification.read ? 'read' : 'unread'}</Status></div><p className="mt-1 text-sm text-muted-foreground">{notification.message}</p><p className="mt-2 font-mono text-[10px] text-muted-foreground">{dateTime(notification.createdAt)}</p></div></button>)}</QueryState></Card></>; }

type ModuleMap = Record<string, () => Promise<Record<string, unknown>>>;

function _resolveComponent(
  mod: Record<string, unknown>,
  name: string,
): ComponentType | undefined {
  const fns = Object.values(mod).filter(
    (v) => typeof v === "function",
  ) as ComponentType[];
  return (
    (mod.default as ComponentType) ||
    (mod.Preview as ComponentType) ||
    (mod[name] as ComponentType) ||
    fns[fns.length - 1]
  );
}

function PreviewRenderer({
  componentPath,
  modules,
}: {
  componentPath: string;
  modules: ModuleMap;
}) {
  const [Component, setComponent] = useState<ComponentType | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    setComponent(null);
    setError(null);

    async function loadComponent(): Promise<void> {
      const key = `./components/mockups/${componentPath}.tsx`;
      const loader = modules[key];
      if (!loader) {
        setError(`No component found at ${componentPath}.tsx`);
        return;
      }

      try {
        const mod = await loader();
        if (cancelled) {
          return;
        }
        const name = componentPath.split("/").pop()!;
        const comp = _resolveComponent(mod, name);
        if (!comp) {
          setError(
            `No exported React component found in ${componentPath}.tsx\n\nMake sure the file has at least one exported function component.`,
          );
          return;
        }
        setComponent(() => comp);
      } catch (e) {
        if (cancelled) {
          return;
        }

        const message = e instanceof Error ? e.message : String(e);
        setError(`Failed to load preview.\n${message}`);
      }
    }

    void loadComponent();

    return () => {
      cancelled = true;
    };
  }, [componentPath, modules]);

  if (error) {
    return (
      <pre style={{ color: "red", padding: "2rem", fontFamily: "system-ui" }}>
        {error}
      </pre>
    );
  }

  if (!Component) return null;

  return <Component />;
}

function MockupSandbox({ params }: { params?: Record<string, string | undefined> }) {
  const previewPath = params?.path;

  if (previewPath) {
    return (
      <PreviewRenderer
        componentPath={previewPath}
        modules={discoveredModules}
      />
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-8">
      <div className="text-center max-w-md">
        <h1 className="text-2xl font-semibold text-gray-900 mb-3">
          Component Preview Server
        </h1>
        <p className="text-gray-500 mb-4">
          This server renders individual components for the workspace canvas.
        </p>
      </div>
    </div>
  );
}

function AppRoutes() {
  const operational = (view: ReactNode) => <RequireAuth><RequireRole roles={['admin', 'staff']}><AdminShell>{view}</AdminShell></RequireRole></RequireAuth>;
  const administrator = (view: ReactNode) => <RequireAuth><RequireRole roles={['admin']}><AdminShell>{view}</AdminShell></RequireRole></RequireAuth>;
  const customer = (page?: 'home' | 'device' | 'workspace' | 'receipts' | 'notifications' | 'profile') => <RequireAuth><RequireRole roles={['customer']}><CustomerHome page={page} /></RequireRole></RequireAuth>;
  return <Switch><Route path="/" component={Landing} /><Route path="/sign-in/*?" component={() => <AuthPage />} /><Route path="/sign-up/*?" component={() => <AuthPage signUp />} /><Route path="/forgot-password" component={ForgotPasswordPage} /><Route path="/reset-password" component={ResetPasswordPage} /><Route path="/admin/dashboard" component={() => operational(<Dashboard />)} /><Route path="/admin/charging/new" component={() => operational(<ChargingNew />)} /><Route path="/admin/charging" component={() => operational(<Charging />)} /><Route path="/admin/workspace" component={() => operational(<Workspace />)} /><Route path="/admin/inventory" component={() => operational(<Inventory />)} /><Route path="/admin/sales" component={() => operational(<Sales />)} /><Route path="/admin/customers" component={() => operational(<Customers />)} /><Route path="/admin/transactions" component={() => operational(<Transactions />)} /><Route path="/admin/history" component={() => operational(<HistoryPage />)} /><Route path="/admin/analytics" component={() => administrator(<Suspense fallback={<LoadingState />}><AdminAnalytics /></Suspense>)} /><Route path="/admin/receipts/:receiptId" component={(props) => operational(<Suspense fallback={<LoadingState />}><ReceiptDetailPage params={props.params} /></Suspense>)} /><Route path="/admin/receipts" component={() => operational(<Receipts />)} /><Route path="/admin/notifications" component={() => operational(<OperationalNotifications />)} /><Route path="/admin/staff" component={() => administrator(<StaffManagement />)} /><Route path="/admin/settings" component={() => administrator(<SettingsPage />)} /><Route path="/staff/dashboard" component={() => operational(<Dashboard />)} /><Route path="/customer" component={() => customer()} /><Route path="/customer/device" component={() => customer('device')} /><Route path="/customer/workspace" component={() => customer('workspace')} /><Route path="/customer/receipts/:receiptId" component={(props) => <RequireAuth><RequireRole roles={['customer']}><Suspense fallback={<LoadingState />}><ReceiptDetailPage customer params={props.params} /></Suspense></RequireRole></RequireAuth>} /><Route path="/customer/receipts" component={() => customer('receipts')} /><Route path="/customer/notifications" component={() => customer('notifications')} /><Route path="/customer/profile" component={() => customer('profile')} /><Route path="/preview/:path*" component={MockupSandbox} /><Route component={NotFound} /></Switch>;
}
function App() { return <Router base={import.meta.env.BASE_URL.replace(/\/$/, '')}><OfflineBanner /><ErrorBoundary><AppRoutes /></ErrorBoundary></Router>; }
export default App;
